export interface AnimeFranchiseResponse {
  /** Raiz da franquia, mesmo quando o anime consultado é outra temporada */
  root: AnimeResponse
  /**
   * A raiz mais a cadeia de `SEQUEL` a partir dela entre os membros, na ordem da cadeia,
   * só com formato de série (`TV`, `TV_SHORT`, `ONA`)
   * @nullable
   */
  seasons?: AnimeResponse[] | null
  /**
   * Membros fora de `seasons` com formato `MOVIE`. Ordenados por `year`/`season`
   * @nullable
   */
  movies?: AnimeResponse[] | null
  /**
   * Membros fora de `seasons` de qualquer outro formato (`OVA`, `SPECIAL`, `TV` fora da
   * cadeia, ...). Ordenados por `year`/`season`
   * @nullable
   */
  specials?: AnimeResponse[] | null
}

/**
 * Tipo de raiz. `MANUAL` = franquia criada à mão (`POST /v1/metadata/franchises`);
 * `NATURAL` = as demais raízes.
 */
export type FranchiseKind = (typeof FranchiseKind)[keyof typeof FranchiseKind]

export const FranchiseKind = {
  NATURAL: 'NATURAL',
  MANUAL: 'MANUAL',
} as const

/**
 * Nova atribuição de franquia do anime
 */
export interface AnimeFranchiseAssignmentRequest {
  assignment: FranchiseAssignment
  /** Raiz de destino. Obrigatório com `MANUAL_MEMBER` e proibido nos outros valores */
  rootId?: AnilistId | null
}

/**
 * Anime que vira raiz da nova franquia manual
 */
export interface CreateFranchiseRequest {
  rootAnilistId: AnilistId
}

/**
 * Resumo de uma franquia pra listagem
 */
export interface FranchiseSummary {
  root: AnimeBindingSummary
  kind: FranchiseKind
  /** Quantidade de membros, contando a raiz */
  memberCount: number
}

/**
 * Envelope paginado de franquias
 */
export type FranchiseSummaryPage = Page & {
  data: FranchiseSummary[]
}

/**
 * Envelope paginado de resumos de anime
 */
export type AnimeBindingSummaryPage = Page & {
  data: AnimeBindingSummary[]
}

/**
 * Membro da franquia
 */
export interface FranchiseMember {
  anime: AnimeResponse
  /** Atribuição do membro (`AUTO`, `MANUAL_MEMBER` ou `MANUAL_ROOT`; membro nunca é `HIDDEN`) */
  assignment: FranchiseAssignment
  /** Pai automático do membro, mesmo que ele esteja em outra franquia */
  autoParentId?: AnilistId | null
}

/**
 * Anime da coleção com aresta pra algum membro, mas em outra franquia ou oculto. Um item
 * por anime, com a aresta de menor id (as demais estão em `edges`), ordenados por
 * `anilistId`
 */
export interface FranchiseRelatedAnime {
  anime: AnimeBindingSummary
  /** Raiz da franquia em que o anime está hoje; `null` se está oculto */
  currentRoot?: AnimeBindingSummary | null
  /** Tipo da aresta como gravada (ex.: `SEQUEL`, `SIDE_STORY`) */
  relationType: string
  /** Membro na outra ponta da aresta */
  memberId: AnilistId
}

/**
 * Franquia detalhada pra organização no portal
 */
export interface FranchiseDetail {
  root: AnimeResponse
  kind: FranchiseKind
  /**
   * Membros da franquia, incluindo a raiz, ordenados por `anilistId`
   * @nullable
   */
  members?: FranchiseMember[] | null
  /** @nullable */
  related?: FranchiseRelatedAnime[] | null
  /**
   * Arestas entre membros e entre membros e `related`, pro desenho
   * @nullable
   */
  edges?: AnimeRelationEdge[] | null
  /**
   * Prévia de `seasons` em `GET /v1/metadata/animes/{anilistId}/franchise`
   * @nullable
   */
  seasons?: AnilistId[] | null
  /**
   * Prévia de `movies`
   * @nullable
   */
  movies?: AnilistId[] | null
  /**
   * Prévia de `specials`
   * @nullable
   */
  specials?: AnilistId[] | null
}

/**
 * Payload de binding TMDB
 */
export interface TmdbBindingRequest {
  tmdbId: TmdbId
  mediaType: TmdbMediaType
}

/**
 * Anime da AniList pra propor o binding TMDB
 */
export interface TmdbBindingProposalRequest {
  anilistId: AnilistId
}

/**
 * Ficha resumida da série (`mediaType` `TV`) ou filme (`MOVIE`) vinculado. A ficha é
 * buscada no TMDB sem `language`, então os textos (título, sinopse, gêneros) vêm no idioma
 * padrão do TMDB (`en-US`), não em `tmdb.default-language`. Campos que só existem num dos
 * tipos vêm `null` no outro.
 */
export interface TmdbBindingDetails {
  /**
   * Nome da série (`name`) ou título do filme (`title`)
   * @nullable
   */
  title?: string | null
  /**
   * Nome no idioma original (`original_name` / `original_title`)
   * @nullable
   */
  originalTitle?: string | null
  originalLanguage?: LanguageCode | null
  /**
   * Sinopse
   * @nullable
   */
  overview?: string | null
  /**
   * Data de estreia (`first_air_date`) ou de lançamento (`release_date`), em ISO-8601
   * @nullable
   */
  releaseDate?: string | null
  /**
   * Status no TMDB (ex.: `Ended`, `Returning Series`, `Released`)
   * @nullable
   */
  status?: string | null
  /**
   * Quantidade de temporadas; só `TV`
   * @nullable
   */
  numberOfSeasons?: number | null
  /**
   * Quantidade de episódios; só `TV`
   * @nullable
   */
  numberOfEpisodes?: number | null
  /**
   * Duração em minutos; só `MOVIE`
   * @nullable
   */
  runtime?: number | null
  /** Nomes dos gêneros, no idioma da ficha */
  genres?: string[]
  voteAverage?: VoteAverage | null
  /**
   * Caminho relativo do poster principal (`poster_path` cru do TMDB)
   * @nullable
   */
  posterPath?: string | null
  /** URL absoluta do poster principal (tamanho `w342`) */
  posterUrl?: ImageUrl | null
  /** URL absoluta do backdrop principal (tamanho `original`) */
  backdropUrl?: ImageUrl | null
}

/**
 * Série ou filme do TMDB proposto pro anime, pelo mapeamento do anibridge. `tmdbId` e
 * `mediaType` são exatamente o payload de `POST /v1/metadata/animes/{anilistId}/tmdb/binding`.
 */
export interface TmdbBindingProposalResponse {
  tmdbId: TmdbId
  mediaType: TmdbMediaType
  /**
   * Ficha do título proposto, como está no TMDB — mesma ficha devolvida no estado do
   * binding (`TmdbAnimeStateResponse.details`), pra conferir se a proposta aponta pro
   * título certo antes de vincular.
   */
  details: TmdbBindingDetails
}

/**
 * Overrides TMDB — todos os campos opcionais; `null` significa "não sobrepõe".
 * Também usado como body de PUT (body com todos `null` apaga a linha); os campos
 * `*PreviewUrl` são só de leitura, ignorados num PUT.
 */
export interface TmdbOverrides {
  /** @nullable */
  title?: string | null
  /** @nullable */
  synopsis?: string | null
  /**
   * Caminho relativo do poster (`filePath` cru do TMDB)
   * @nullable
   */
  posterPath?: string | null
  /**
   * URL completa do CDN do TMDB, já pronta pra exibir (derivada de `posterPath`)
   * @nullable
   */
  posterPreviewUrl?: string | null
  /** @nullable */
  backdropPath?: string | null
  /**
   * URL completa do CDN do TMDB, já pronta pra exibir (derivada de `backdropPath`)
   * @nullable
   */
  backdropPreviewUrl?: string | null
  /** @nullable */
  logoPath?: string | null
  /**
   * URL completa do CDN do TMDB, já pronta pra exibir (derivada de `logoPath`)
   * @nullable
   */
  logoPreviewUrl?: string | null
}

/**
 * Estado TMDB do anime (binding + overrides + dados do próprio TMDB)
 */
export interface TmdbAnimeStateResponse {
  tmdbId?: TmdbId | null
  mediaType?: TmdbMediaType | null
  /** @nullable */
  createdAt?: string | null
  overrides?: TmdbOverrides | null
  /**
   * Dados da série ou filme vinculado, como estão no TMDB — sem overrides aplicados, pra
   * conferir se o binding aponta pro título certo. Lidos da ficha do TMDB (cache-first).
   */
  details: TmdbBindingDetails
}

/**
 * Opção textual do schema de overrides. `value` é o que o front grava como override;
 * `language` é apenas para exibição (badge de idioma).
 */
export interface TmdbLocalizedOption {
  /** @nullable */
  value?: string | null
  /**
   * ISO 639-1; `null` quando o TMDB não informa
   * @nullable
   */
  language?: string | null
}

/**
 * Opção de imagem do schema de overrides. `value` é o `filePath` cru; `previewUrl`
 * é a URL completa pronta para renderizar.
 */
export interface TmdbImageOption {
  /**
   * `filePath` relativo (grava em overrides)
   * @nullable
   */
  value?: string | null
  /**
   * URL completa para preview
   * @nullable
   */
  previewUrl?: string | null
  /**
   * ISO 639-1; `null` para variantes neutras
   * @nullable
   */
  language?: string | null
  /** @nullable */
  width?: number | null
  /** @nullable */
  height?: number | null
}

/**
 * Opções concretas por campo que aceita override (traduções e imagens)
 */
export interface TmdbOverridesSchema {
  /** @nullable */
  title?: TmdbLocalizedOption[] | null
  /** @nullable */
  synopsis?: TmdbLocalizedOption[] | null
  /** @nullable */
  posterPath?: TmdbImageOption[] | null
  /** @nullable */
  backdropPath?: TmdbImageOption[] | null
  /** @nullable */
  logoPath?: TmdbImageOption[] | null
}

/**
 * Episódio numa temporada do schema de pairing
 */
export interface TmdbFilePairingSchemaEpisode {
  /** @nullable */
  episodeNumber?: number | null
  /** @nullable */
  name?: string | null
  /**
   * Sinopse curta do episódio
   * @nullable
   */
  overview?: string | null
  /**
   * Data de estreia ISO-8601 (`null` para episódios futuros)
   * @nullable
   */
  airDate?: string | null
  /**
   * Duração em minutos
   * @nullable
   */
  runtime?: number | null
  /**
   * Nota média do TMDB
   * @nullable
   */
  voteAverage?: number | null
  /**
   * Total de votos que compõem a nota média
   * @nullable
   */
  voteCount?: number | null
  /**
   * Classificação do TMDB (ex.: `standard`, `finale`)
   * @nullable
   */
  episodeType?: string | null
  /**
   * Valor a mandar em `thumbnailPath` do PUT
   * @nullable
   */
  defaultStillPath?: string | null
  /**
   * URL já dimensionada para preview no modal
   * @nullable
   */
  defaultStillPreviewUrl?: string | null
}

/**
 * Temporada no schema de pairing
 */
export interface TmdbFilePairingSchemaSeason {
  /**
   * `0` = specials
   * @nullable
   */
  seasonNumber?: number | null
  /** @nullable */
  name?: string | null
  /** @nullable */
  episodes?: TmdbFilePairingSchemaEpisode[] | null
}

/**
 * Estrutura da série TMDB vinculada — temporadas com episódios. Consumido pelo
 * modal do PUT do pairing, para o cliente não precisar adivinhar temporada/episódio.
 */
export interface TmdbFilePairingSchema {
  /** @nullable */
  seasons?: TmdbFilePairingSchemaSeason[] | null
}

/**
 * Payload de PUT — descreve o estado completo do pairing. Todos campos opcionais;
 * `null` zera aquela dimensão. Para remover a linha inteira use DELETE. Os campos
 * `episode*` vêm prontos do `TmdbFilePairingSchemaEpisode` escolhido no modal — o
 * servidor não rebusca no TMDB, só persiste o que o cliente mandar.
 */
export interface TmdbFilePairingRequest {
  /** @nullable */
  seasonNumber?: number | null
  /** @nullable */
  episodeNumber?: number | null
  /**
   * `filePath` relativo do CDN do TMDB
   * @nullable
   */
  thumbnailPath?: string | null
  /** @nullable */
  episodeName?: string | null
  /** @nullable */
  episodeOverview?: string | null
  /**
   * Data de estreia ISO-8601
   * @nullable
   */
  episodeAirDate?: string | null
  /**
   * Duração em minutos
   * @nullable
   */
  episodeRuntime?: number | null
  /** @nullable */
  episodeVoteAverage?: number | null
  /** @nullable */
  episodeVoteCount?: number | null
  /**
   * Classificação do TMDB (ex.: `standard`, `finale`)
   * @nullable
   */
  episodeType?: string | null
}

/**
 * Como a proposta de pairing é calculada.
 *
 * - `ANIBRIDGE` — número do episódio extraído do nome do arquivo, convertido pelo
 *   anibridge pra temporada/episódio da série vinculada (o mesmo do pairing automático da
 *   ingestão).
 * - `CONTINUITY` — episódio seguinte ao do arquivo pareado anterior, pela estrutura da
 *   série no TMDB; não consulta o anibridge.
 */
export type TmdbFilePairingStrategy =
  (typeof TmdbFilePairingStrategy)[keyof typeof TmdbFilePairingStrategy]

export const TmdbFilePairingStrategy = {
  ANIBRIDGE: 'ANIBRIDGE',
  CONTINUITY: 'CONTINUITY',
} as const

/**
 * Anime cujos arquivos devem receber a proposta de pairing
 */
export interface TmdbFilePairingProposalRequest {
  anilistId: AnilistId
  strategy?: TmdbFilePairingStrategy
}

/**
 * Comparação da proposta com o par atual do arquivo.
 *
 * - `NEW` — o arquivo não tem par gravado.
 * - `SAME` — a proposta é igual ao par gravado.
 * - `REPLACE` — a proposta substituiria um par gravado diferente.
 */
export type TmdbFilePairingChange =
  (typeof TmdbFilePairingChange)[keyof typeof TmdbFilePairingChange]

export const TmdbFilePairingChange = {
  NEW: 'NEW',
  SAME: 'SAME',
  REPLACE: 'REPLACE',
} as const

/**
 * Resultado da proposta pra um arquivo. Entre colchetes, a estratégia em que o status
 * aparece.
 *
 * - `PAIRED` [`ANIBRIDGE`, `CONTINUITY`] — há proposta: `seasonNumber`/`episodeNumber`
 *   resolvidos e confirmados no TMDB. Na `ANIBRIDGE` pode vir com `usedByFileId` (episódio
 *   já usado por outro arquivo); na `CONTINUITY` esse caso vira `EPISODE_IN_USE`.
 * - `NO_EPISODE_NUMBER` [`ANIBRIDGE`] — não deu pra extrair um número de episódio do nome
 *   do arquivo.
 * - `NOT_MAPPED` [`ANIBRIDGE`] — o número extraído não cai em nenhum mapeamento do
 *   anibridge pra série vinculada.
 * - `AMBIGUOUS_ABSOLUTE_NUMBERING` [`ANIBRIDGE`] — o arquivo usa numeração absoluta, mas o
 *   mapeamento do anibridge não cobre a temporada isolada com segurança pra aplicar o
 *   offset.
 * - `NOT_FOUND_IN_TMDB` [`ANIBRIDGE`] — o anibridge resolveu `seasonNumber`/`episodeNumber`,
 *   mas o episódio não existe no TMDB (temporada inexistente, episódio fora da temporada,
 *   ou a busca no TMDB falhou) — o anibridge pode estar dessincronizado do TMDB.
 * - `NO_MAPPING` [`ANIBRIDGE`] — o anibridge não tem mapeamento do anime pra série
 *   vinculada (vale pra todos os arquivos).
 * - `CONFLICTING_MAPPING` [`ANIBRIDGE`] — o mapeamento do anibridge pra série vinculada tem
 *   temporadas conflitantes e não é usado (vale pra todos os arquivos).
 * - `NO_ANCHOR` [`CONTINUITY`] — não há arquivo pareado antes deste na pasta.
 * - `END_OF_SERIES` [`CONTINUITY`] — não há episódio seguinte ao da âncora (fim da última
 *   temporada da série).
 * - `EPISODE_IN_USE` [`CONTINUITY`] — o episódio seguinte já está gravado em outro arquivo
 *   ou foi proposto antes pra outro arquivo nesta mesma proposta (`usedByFileId`). Não vem
 *   pré-selecionado; o arquivo continua sendo a âncora do próximo.
 */
export type TmdbFilePairingProposalStatus =
  (typeof TmdbFilePairingProposalStatus)[keyof typeof TmdbFilePairingProposalStatus]

export const TmdbFilePairingProposalStatus = {
  PAIRED: 'PAIRED',
  NO_EPISODE_NUMBER: 'NO_EPISODE_NUMBER',
  NOT_MAPPED: 'NOT_MAPPED',
  AMBIGUOUS_ABSOLUTE_NUMBERING: 'AMBIGUOUS_ABSOLUTE_NUMBERING',
  NOT_FOUND_IN_TMDB: 'NOT_FOUND_IN_TMDB',
  NO_MAPPING: 'NO_MAPPING',
  CONFLICTING_MAPPING: 'CONFLICTING_MAPPING',
  NO_ANCHOR: 'NO_ANCHOR',
  END_OF_SERIES: 'END_OF_SERIES',
  EPISODE_IN_USE: 'EPISODE_IN_USE',
} as const

/**
 * Proposta de pairing de um arquivo de vídeo
 */
export interface TmdbFilePairingProposal {
  fileId: FileId
  /** Nome do arquivo, de onde o número do episódio é extraído */
  fileName: string
  status: TmdbFilePairingProposalStatus
  /**
   * Temporada do TMDB proposta; preenchida em `PAIRED` e `EPISODE_IN_USE`, e em
   * `NOT_FOUND_IN_TMDB` (aí mostra pra onde o anibridge apontou)
   * @nullable
   */
  seasonNumber?: number | null
  /**
   * Episódio do TMDB proposto; preenchido nos mesmos status que `seasonNumber`
   * @nullable
   */
  episodeNumber?: number | null
  /**
   * Temporada do par gravado hoje pro arquivo; `null` se ele não tem par
   * @nullable
   */
  currentSeasonNumber?: number | null
  /**
   * Episódio do par gravado hoje pro arquivo; `null` se ele não tem par
   * @nullable
   */
  currentEpisodeNumber?: number | null
  /**
   * Comparação da proposta com o par atual; `null` quando não há proposta (qualquer
   * status fora `PAIRED` e `EPISODE_IN_USE`)
   */
  change?: TmdbFilePairingChange | null
  /**
   * Se a proposta deve vir marcada no portal: `change` = `NEW` e episódio sem uso por
   * outro arquivo (`usedByFileId` `null`). Vale igual pras duas estratégias e pra
   * qualquer temporada, inclusive a 0.
   */
  selectedByDefault: boolean
  /**
   * Arquivo âncora de onde a proposta continua (o pareado anterior na pasta); só na
   * `CONTINUITY`, em `PAIRED` e `EPISODE_IN_USE` de arquivo sem par próprio
   */
  basedOnFileId?: FileId | null
  /**
   * Outro arquivo que já usa o episódio proposto — com o par gravado, ou proposto antes
   * dele nesta mesma proposta (na ordem da lista); `null` se ninguém usa
   */
  usedByFileId?: FileId | null
  /**
   * Payload pronto pra `PUT /v1/metadata/files/{fileId}/tmdb-pairing`, com a metadata do
   * episódio proposto no TMDB (thumbnail, nome, sinopse etc.); preenchido em `PAIRED` e
   * `EPISODE_IN_USE` quando o episódio existe no TMDB
   */
  pairing?: TmdbFilePairingRequest | null
}

/**
 * Proposta de pairing de todos os arquivos da pasta do anime
 */
export interface TmdbFilePairingProposalResponse {
  anilistId: AnilistId
  /** Série do TMDB vinculada ao anime, base da proposta */
  tmdbId: TmdbId
  /** Todos os arquivos de vídeo da pasta do anime, na ordem natural dos nomes */
  files: TmdbFilePairingProposal[]
}

/**
 * Identificador da preferência
 * @minLength 1
 */
export type SettingKey = string

/**
 * Valor cru da preferência (interpretado pelo tipo no ponto de leitura)
 */
export type SettingValue = string

/**
 * Preferência do admin; o `value` de preferências `secret` vem mascarado, nunca o valor cru
 */
export interface SettingResponse {
  key: SettingKey
  /**
   * `***` quando `secret` é `true` (o valor cru nunca é ecoado); senão o valor cru, que pode ser `null` quando a preferência ainda não foi configurada
   * @nullable
   */
  value?: string | null
  /** `true` para preferências sensíveis (ex.: tokens) — o portal renderiza como senha */
  secret: boolean
  /** `true` se há um valor não-vazio cadastrado (útil para secrets, cujo `value` é mascarado) */
  configured: boolean
  /** Momento da última atualização */
  updatedAt: string
}

/**
 * Payload de `PUT /v1/settings/{key}`
 */
export interface UpdateSettingRequest {
  /** Novo valor; string vazia é permitida (ex.: limpar um secret) */
  value: SettingValue
}

/**
 * Lista de preferências, ordenada pela chave
 */
export type SettingList = SettingResponse[]

/**
 * Severidade da notificação
 */
export type NotificationLevel =
  (typeof NotificationLevel)[keyof typeof NotificationLevel]

export const NotificationLevel = {
  INFO: 'INFO',
  WARNING: 'WARNING',
  ERROR: 'ERROR',
} as const

/**
 * Notificação de observabilidade — hoje geradas pela ingestão (conclusão, falha geral e
 * falhas parciais do binding automático de cada título).
 */
export interface NotificationResponse {
  /** Id da notificação */
  id: number
  level: NotificationLevel
  /** Texto pronto para exibir ao admin */
  message: string
  /**
   * Pasta do catalog do título a que a notificação se refere — o portal usa para linkar a
   * revisão. `null` quando a notificação não é sobre um título (ex.: conclusão da
   * ingestão).
   */
  folderId?: FolderId | null
  /**
   * Título a que a notificação se refere; `null` nas mesmas condições de `folderId`
   * @nullable
   */
  title?: string | null
  /**
   * URL da capa em tamanho pequeno (ícone); `null` quando não há capa conhecida
   * @nullable
   */
  coverImageUrl?: string | null
  /** `true` se o admin já marcou como lida */
  read: boolean
  /** Momento em que a notificação foi gerada */
  createdAt: string
}

/**
 * Envelope paginado de notificações
 */
export type NotificationPage = Page & {
  data: NotificationResponse[]
}

/**
 * Contagem de notificações não-lidas
 */
export interface UnreadCountResponse {
  count: number
}

/**
 * Tipo de um evento do stream SSE `GET /v1/notifications/events`. É também o `event:`
 * (nome) da mensagem SSE, então o cliente pode tanto registrar um listener por nome
 * (`addEventListener('NEW', ...)`) quanto ler o campo `type` do payload.
 *
 * - `NEW` — uma notificação acabou de ser criada.
 */
export type NotificationEventType =
  (typeof NotificationEventType)[keyof typeof NotificationEventType]

export const NotificationEventType = {
  NEW: 'NEW',
} as const

/**
 * Payload (`data:`, JSON) de cada mensagem do stream SSE `GET /v1/notifications/events` —
 * o endpoint não é descrito em `paths` (Server-Sent Events não é modelável pelo gerador
 * `jaxrs-spec`), só este payload.
 *
 * O stream é aberto com `EventSource` (`GET`, `Accept: text/event-stream`) e fica aberto
 * indefinidamente, sem evento inicial: a primeira mensagem só chega quando uma notificação
 * nova é criada. Cada mensagem tem `event:` igual ao `type` e o `data:` com este objeto. O
 * stream só avisa de notificações novas — o histórico e a contagem de não-lidas continuam
 * em `GET /v1/notifications` e `GET /v1/notifications/unread-count`; um cliente que
 * reconecta depois de uma queda deve recarregar por eles o que pode ter perdido.
 */
export interface NotificationEvent {
  type: NotificationEventType
  /** A notificação recém-criada, no mesmo formato da listagem — sempre com `read = false` */
  notification: NotificationResponse
}

/**
 * Payload ou parâmetros inválidos (`VALIDATION_ERROR`), ou regra de negócio violada (`BUSINESS_RULE_VIOLATION`)
 */
export type BadRequestResponse = ApiError

/**
 * Recurso inexistente (`RESOURCE_NOT_FOUND`)
 */
